LwpObjectStream::~LwpObjectStream() { ReleaseBuffer(); }
/**
* @descr  release object buffer
*/
void LwpObjectStream::ReleaseBuffer()
{
    m_BigBuffer.clear();
    m_pContentBuf = nullptr;
}
