/**
* @descr  Quick read double
*/
double LwpObjectStream::QuickReadDouble()
{
    union {
        double d;
        sal_uInt8 c[8];
    } s;
    memset(s.c, 0, sizeof(s.c));
    QuickRead(s.c, sizeof(s.c));
#if defined(OSL_BIGENDIAN)
    for (size_t i = 0; i < 4; ++i)
        std::swap(s.c[i], s.c[7 - i]);
#endif
    return s.d;
}
